tasks.setup:
// VALUE: number is copied — b is independent of a
let a = 10;
let b = a;
a = 99;
console.log(b);   // b kept its own copy

// REFERENCE: object is shared — q aliases p
let p = { n: 1 };
let q = p;
q.n = 99;         // mutate the one shared object via q
console.log(p.n); // p sees it too — same object

// array aliasing: b is the SAME array as a
let a = [1, 2, 3];
let b = a;
b[0] = 99;
console.log(a[0]);   // 99 — shared array

// separate literals: two different objects
let p = { v: 1 };
let r = { v: 1 };
r.v = 7;
console.log(p.v);    // 1 — p is its own object

